@font-face {
	font-family: "Theme-Font";
	src: url('https://cdn.jsdelivr.net/gh/projectnoonnu/noonfonts_three@1.0/D2Coding.woff') format('woff');
	font-weight: normal;
	font-display: swap;
}

@font-face {
	font-family: "Material Symbols Outlined";
	font-style: normal;
	src: url(data:application/octet-stream;base64,);
}

.nav-folder-title-content::before,
.nav-file-title-content::before {
	font-family: 'Material Symbols Outlined';
	font-weight: normal;
	font-style: normal;
	font-size: 14px;
	line-height: 0;
	letter-spacing: normal;
	text-transform: none;
	display: inline-block;
	white-space: nowrap;
	word-wrap: normal;
	direction: ltr;
	-webkit-font-feature-settings: 'liga';
	-webkit-font-smoothing: antialiased;
}

.inline-title::before {
	font-family: 'Material Symbols Outlined';
	font-weight: normal;
	font-style: normal;
	font-size: 14px;
	line-height: 0;
	letter-spacing: normal;
	text-transform: none;
	display: inline-block;
	white-space: nowrap;
	word-wrap: normal;
	direction: ltr;
	-webkit-font-feature-settings: 'liga';
	-webkit-font-smoothing: antialiased;
}


@keyframes BackgroundGradient {
	0% {
		background-position: 0 50%;
	}
	50% {
		background-position: 100% 50%;
	}
	100% {
		background-position: 0 50%;
	}
}


body {
	--font-text-theme: Theme-Font, sans-serif;
	--radius-s: 0px;
	--radius-m: 0px;
	--radius-l: 0px;
	--input-radius: 0px;
	--tab-radius-active: 0px;
	--checkbox-radius: 0px;
	--toggle-radius: 0px;
	--toggle-thumb-radius: 0px;
	--slider-thumb-radius: 0px;
}

.workspace-tab-header.is-active::before, .workspace-tab-header.is-active::after {
	display: none;
}

svg * {
	stroke-linecap: square;
	stroke-linejoin: miter;
	rx: 0;
	ry: 0;
}

.menu {
	padding: var(--size-2-1);
}

.menu-item {
	padding: var(--size-4-1) var(--size-4-2);
}

.menu-separator {
	margin: var(--size-2-1) calc(var(--size-2-1) * -1);
}

.nav-folder-title-content::before {
	position:relative;
	top: 3px;
	margin-right: 0.25em;
	content: "folder";
	font-size: 16px;
}

.nav-file-title-content::before {
	margin-right: 0.25em;
	position:relative;
	top: 3px;
}

.markdown-preview-view {
	--p-spacing: 10px;
	--heading-spacing: 30px;
}

.markdown-preview-view :is(h1,h2,h3,h4,h5,h6) {
	position: relative;
}


.markdown-preview-view .inline-title {
	width: 100%;
}

.markdown-preview-view .inline-title,
.markdown-source-view .inline-title {
	position: relative;
	border-radius: 4px;
	padding: 0.5em 0.5em;
	display: inline-block;
}

.markdown-source-view .inline-title::before {
	position:relative;
	top: 5px;
	margin-right: 0.5em;
	content: "edit";
	font-size: 24px;
}

.markdown-preview-view :is(h1,h2,h3,h4,h5,h6)::after {
	content: "";
	position: absolute;
	left: 0;
	bottom: calc(1rem * -0.1);
	width: 100%;
	height: 1px;
}

.cm-line.HyperMD-header::after {
	content: "";
	position: absolute;
	left: 0;
	bottom: calc(var(--p-spacing)* 0.3);
	width: 100%;
	height: 1px;
}

.cm-s-obsidian .cm-line.HyperMD-header {
	padding-bottom: calc(var(--p-spacing)/2);
}

.markdown-preview-view .inline-title,
.markdown-source-view .inline-title {
	background: linear-gradient(132deg, var(--myst-gradient-color1), var(--myst-gradient-color2), var(--myst-gradient-color3), var(--myst-gradient-color4));
	background-size: 600% 600%;
	animation: BackgroundGradient 15s ease infinite;
}

.markdown-preview-view :is(h1,h2,h3,h4,h5,h6)::after {
	background-color: var(--myst-header-line-color);
}


body:not(.show-inline-title) .markdown-preview-view h1,
body:not(.show-inline-title) .markdown-source-view .HyperMD-header-1 {
	background: linear-gradient(132deg, var(--myst-gradient-color1), var(--myst-gradient-color2), var(--myst-gradient-color3), var(--myst-gradient-color4));
	background-size: 600% 600%;
	animation: BackgroundGradient 15s ease infinite;
}

.cm-line.HyperMD-header::after {
	background-color: var(--myst-header-line-color);
}

/* highlite (edit) */
.cm-line .cm-highlight {
	background-color: var(--text-hightlight-bg) !important;
	color:black !important;
	padding-left: 0.25em;
	padding-right: 0.25em;
}

/* hightlight(read) */
.markdown-preview-view mark {
	background-color: var(--text-hightlight-bg) !important;
	color:black !important;
	padding-left: 0.25em;
	padding-right: 0.25em;
}

.theme-dark {
	--h1-color: #bcbec4;
	--h2-color: #bcbec4;
	--h3-color: #bcbec4;
	--h4-color: #bcbec4;
	--h5-color: #bcbec4;
	--h6-color: #bcbec4;

	--text-normal: #bcbec4;
	--text-accent: #56a8f5;
	--text-selection: #214283;
	--text-hightlight-bg: #f8f876;
	--bold-color: #90a939;
	--background-primary: #1e1f22;
	--code-background: #404348;

	--myst-header-line-color: rgba(201, 201, 201, 0.314);
	--myst-gradient-color1: #010199;
	--myst-gradient-color2: #015d01;
	--myst-gradient-color3: #580000;
	--myst-gradient-color4: #000000;

	.nav-folder-title-content::before {
		font-variation-settings: 'FILL' 1, 'wght' 400, 'GRAD' 0, 'opsz' 24;
		color: #ffda73;
	}

	.nav-file-title .nav-file-title-content::before {
		content: "draft";
		color: #757177;
	}

	.nav-file-title[data-path$=".md"] .nav-file-title-content::before {
		content: "docs";
		color: #868288;
	}

	.nav-file-title[data-path$=".pdf"] .nav-file-title-content::before {
		content: "picture_as_pdf";
		color: #25af0f;
	}

	.nav-file-title[data-path$=".excalidraw.md"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".canvas"] .nav-file-title-content::before
	{
		content: "category";
		color: #7138ae;
	}

	.nav-file-title[data-path$=".jpg"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".jpeg"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".png"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".gif"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".avif "] .nav-file-title-content::before,
	.nav-file-title[data-path$=".bmp"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".svg"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".webp"] .nav-file-title-content::before
	{
		content: "image";
		color: #932d2d;
	}

	/* strike style (edit) */
	.cm-line .cm-strikethrough {
		color: color-mix(in srgb, var(--text-normal) 50%, transparent);
		font-style: italic;
	}

	/* strike style (read) */
	.markdown-preview-view del {
		color: color-mix(in srgb, var(--text-normal) 50%, transparent);
		font-style: italic;
	}

}

.theme-light {
	::selection {
		color: white;
	}

	--h1-color: #000;
	--h2-color: #000;
	--h3-color: #000;
	--h4-color: #000;
	--h5-color: #000;
	--h6-color: #000;
	--text-normal: #000;

	--text-accent: #4476e5;
	--text-selection: #214283;
	--text-hightlight-bg: #f8f876;
	--bold-color: #90a939;
	--background-primary: #fff;
	--code-background: #efeded;

	--myst-header-line-color: rgba(0, 0, 0, 0.314);
	--myst-gradient-color1: #b0b0ff;
	--myst-gradient-color2: #fc7d7d;
	--myst-gradient-color3: #c77b7b;
	--myst-gradient-color4: #ffffff;

	.nav-folder-title-content::before {
		font-variation-settings: 'FILL' 0, 'wght' 400, 'GRAD' 0, 'opsz' 24;
		color: #615268;
	}

	.nav-file-title .nav-file-title-content::before {
		content: "draft";
		color: #9c84a8;
	}

	.nav-file-title[data-path$=".md"] .nav-file-title-content::before {
		content: "docs";
		color: #7d6987;
	}

	.nav-file-title[data-path$=".pdf"] .nav-file-title-content::before {
		content: "picture_as_pdf";
		color: #1f930d;
	}

	.nav-file-title[data-path$=".excalidraw.md"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".canvas"] .nav-file-title-content::before
	{
		content: "category";
		color: #9358d1;
	}

	.nav-file-title[data-path$=".jpg"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".jpeg"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".png"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".gif"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".avif "] .nav-file-title-content::before,
	.nav-file-title[data-path$=".bmp"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".svg"] .nav-file-title-content::before,
	.nav-file-title[data-path$=".webp"] .nav-file-title-content::before
	{
		content: "image";
		color: #c80505;
	}

	/* strike style (edit) */
	.cm-line .cm-strikethrough {
		color: color-mix(in srgb, var(--text-normal) 30%, transparent);
		font-style: italic;
	}

	/* strike style (read) */
	.markdown-preview-view del {
		color: color-mix(in srgb, var(--text-normal) 30%, transparent);
		font-style: italic;
	}
}
